    /*
     * Add to the Goals
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	InvestmentPolicy
     */
    public InvestmentPolicy addToGoals( UUID parentId, WealthGoal addTo ) {
	    LOGGER.info("handling AssignGoalsToInvestmentPolicyEvent - " );
	    
	    InvestmentPolicy parentEntity = repository.findById(parentId).get();
	    WealthGoal child = registry.project( WealthGoal.class, addTo.getWealthGoalId());
	    
	    parentEntity.getGoals().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Goals
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	InvestmentPolicy
     */
	public InvestmentPolicy removeFromGoals( UUID parentId, WealthGoal removeFrom ) {
	    LOGGER.info("handling RemoveGoalsFromInvestmentPolicyEvent " );
	
	    InvestmentPolicy parentEntity = repository.findById(parentId).get();
	    WealthGoal child = registry.project( WealthGoal.class, removeFrom.getWealthGoalId());
	    
	    parentEntity.getGoals().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



